const APP_VERSION='2.8.1-web.7';
const app=document.getElementById('app');
const state={route:'splash',navStack:[],historyDraftId:null,historyDraftRoute:null,_last:null};
const num=v=>{const x=parseFloat(String(v??'').replace(',','.'));return Number.isFinite(x)?x:null};
const fmt=(v,d=2)=>Number.isFinite(v)?v.toFixed(d).replace(/\.?0+$/,''):'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const historyKey='operator_dng_history_v1';
function history(){try{return JSON.parse(localStorage.getItem(historyKey)||'[]')}catch{return[]}}
function saveHistory(entry){const list=history();const id=crypto.randomUUID?.()||String(Date.now());list.unshift({...entry,id,ts:Date.now()});localStorage.setItem(historyKey,JSON.stringify(list.slice(0,150)));return id}
function updateHistory(id,entry){const list=history();const i=list.findIndex(x=>x.id===id);if(i<0)return false;list[i]={...list[i],...entry,ts:Date.now()};localStorage.setItem(historyKey,JSON.stringify(list.slice(0,150)));return true}
function recordCalculation(entry){
  state._last=entry;
  if(!entry)return;
  if(state.historyDraftRoute!==state.route){state.historyDraftId=null;state.historyDraftRoute=state.route}
  if(state.historyDraftId && updateHistory(state.historyDraftId,entry))return;
  state.historyDraftId=saveHistory(entry);
  state.historyDraftRoute=state.route;
}
Object.defineProperty(state,'last',{get(){return state._last},set(v){recordCalculation(v)}});
function resetHistoryDraft(){state.historyDraftId=null;state.historyDraftRoute=null;state._last=null}
function clearHistory(){localStorage.removeItem(historyKey);resetHistoryDraft()}
function go(route){
  if(route===state.route)return;
  if(state.route)state.navStack.push(state.route);
  resetHistoryDraft();
  state.route=route;render();scrollTo(0,0)
}
function goBack(){
  if(state.route==='assistant' && state.assistantIndex!==undefined && state.assistantIndex!==null){state.assistantIndex=null;renderAssistant();scrollTo(0,0);return}
  const prev=state.navStack.pop();
  if(prev){resetHistoryDraft();state.route=prev;render();scrollTo(0,0);return}
  if(state.route!=='home'){resetHistoryDraft();state.route='home';render();scrollTo(0,0)}
}
function topbar(title){return `<div class="topbar"><button class="back" onclick="goBack()">‹</button><h1>${esc(title)}</h1></div>`}
function bottomNav(active='home'){const canBack=state.route!=='home'||state.navStack.length>0;return `<nav class="bottom-nav"><button class="nav-btn back-nav" onclick="goBack()" ${canBack?'':'disabled'}><span>‹</span><span>Назад</span></button><button class="nav-btn ${active==='home'?'active':''}" onclick="go('home')"><span>⌂</span><span>Главная</span></button><button class="nav-btn ${active==='history'?'active':''}" onclick="go('history')"><span>◷</span><span>История</span></button><button class="nav-btn ${active==='reference'?'active':''}" onclick="go('reference')"><span>☰</span><span>Справочник</span></button></nav>`}
function screen(body,active='home'){return `<div class="screen">${body}</div>${bottomNav(active)}`}
function field(id,label,opts=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" inputmode="decimal" autocomplete="off" ${opts}></div>`}
function selectField(id,label,options,value){return `<div class="field"><label>${label}</label><select id="${id}">${options.map(o=>`<option ${String(o)===String(value)?'selected':''}>${o}</option>`).join('')}</select></div>`}
function resultCard(title,value,error=''){return `<div class="card result"><h4>${esc(title)}</h4>${value?`<div class="value">${esc(value)}</div>`:`<div class="error">${esc(error||'Заполните параметры')}</div>`}</div>`}
function bind(ids,fn){ids.forEach(id=>document.getElementById(id)?.addEventListener('input',fn));ids.forEach(id=>document.getElementById(id)?.addEventListener('change',fn))}
function setResult(title,value,error){const el=document.getElementById('liveResult');if(el)el.outerHTML=`<div id="liveResult">${resultCard(title,value,error)}</div>`}
function iconSvg(type){
  const common='class="menu-svg" viewBox="0 0 48 48" aria-hidden="true"';
  if(type==='level')return `<svg ${common}><path d="M10 30c6-7 22-7 28 0v8H10z" fill="#39a9db"/><path d="M10 30c7 4 21 4 28 0" fill="none" stroke="#fff" stroke-width="2.5"/><text x="24" y="23" text-anchor="middle" font-size="20" font-weight="900" fill="#171717">H</text></svg>`;
  if(type==='frequency')return `<svg ${common}><rect x="7" y="7" width="34" height="34" rx="11" fill="#fff3cd" stroke="#f28c00" stroke-width="2"/><text x="24" y="31" text-anchor="middle" font-size="27" font-weight="900" font-style="italic" fill="#171717">F</text></svg>`;
  if(type==='manual')return `<img class="menu-img" src="assets/ic_manual_debit.png" alt="">`;
  if(type==='flow')return `<img class="menu-img" src="assets/ic_well_inflow.png" alt="">`;
  if(type==='sko')return `<svg ${common}><path d="M17 7h14v4l-4 6v5l9 15c1 2-.4 4-2.8 4H14.8c-2.4 0-3.8-2-2.8-4l9-15v-5l-4-6z" fill="#fff" stroke="#171717" stroke-width="2.4"/><path d="M15 34h18l3 5H12z" fill="#38a95a"/><path d="M18 31c4-2 8 2 13 0" fill="none" stroke="#38a95a" stroke-width="4"/></svg>`;
  if(type==='zsp')return `<svg ${common}><rect x="5" y="9" width="38" height="30" rx="9" fill="#fff3cd" stroke="#f28c00" stroke-width="2"/><text x="24" y="30" text-anchor="middle" font-size="17" font-weight="900" fill="#171717">ЗСП</text></svg>`;
  if(type==='pipeLarge')return `<svg ${common}><ellipse cx="24" cy="12" rx="15" ry="7" fill="#d9dde1" stroke="#59636d" stroke-width="2.4"/><path d="M9 12v24c0 4 30 4 30 0V12" fill="#c4cad0" stroke="#59636d" stroke-width="2.4"/><ellipse cx="24" cy="12" rx="8" ry="3.5" fill="#f6f6f6" stroke="#59636d" stroke-width="2"/></svg>`;
  if(type==='pipeSmall')return `<svg ${common}><ellipse cx="24" cy="14" rx="11" ry="5" fill="#d9dde1" stroke="#59636d" stroke-width="2.3"/><path d="M13 14v22c0 3 22 3 22 0V14" fill="#c4cad0" stroke="#59636d" stroke-width="2.3"/><ellipse cx="24" cy="14" rx="5.5" ry="2.4" fill="#f6f6f6" stroke="#59636d" stroke-width="1.8"/></svg>`;
  return type;
}
function menuCard(icon,title,subtitle,route){return `<div class="card menu-card pressable" onclick="go('${route}')"><div class="emoji">${iconSvg(icon)}</div><div class="grow"><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></div><div class="chev">›</div></div>`}

function renderHome(){app.innerHTML=screen(`<section class="hero"><img src="assets/logo.png" alt="Оператор ДНГ"><h1>Расчёт параметров скважины</h1><p>Выберите необходимый расчёт</p></section><main class="content stack">
${menuCard('level','Уровень жидкости в скважине','Определение уровня по замерам','level')}
${menuCard('frequency','Необходимая частота запуска','Расчёт частоты УЭЦН','frequency')}
${menuCard('flow','Определение притока','Три режима ОК, Vкп по таблице или геометрии','flow')}
${menuCard('manual','Ручной замер дебита','Перевод литров и времени замера в м³/сут','manual')}
${menuCard('⚡','Расчёт отпайки ТМПН','Для СУ без ЧРП и для СУ с ЧРП','tap')}
${menuCard('↻','Перевод ПР в УПР','Расчёт времени работы и остановки','upr')}
${menuCard('↻','Перевод УПР в АПВ','Проверка цикла с учётом времени слива','apv')}
${menuCard('sko','Объём СКО','Четыре варианта расчёта кислотной обработки','sko')}
</main>`,'home')}

function renderLevel(){app.innerHTML=screen(`${topbar('Расчёт уровня жидкости')}<main class="content stack">${field('depth','Глубина спуска насоса, м')}<div class="row">${field('pz','Pз')}${field('pd','Pд')}</div>${field('density','Плотность жидкости, кг/м³')}<div id="liveResult">${resultCard('Уровень жидкости','','Заполните все параметры')}</div><button class="btn secondary full" id="clear">Очистить</button></main>`);const calc=()=>{const d=num(depth.value),z=num(pz.value),p=num(pd.value),rho=num(density.value);if([d,z,p,rho].some(v=>v===null)||rho<=0)return setResult('Уровень жидкости','', 'Заполните все параметры');const level=d-((p-z)*10)/(rho/1000);setResult('Уровень жидкости',`${fmt(level)} м`);state.last={title:'Уровень жидкости',method:'Автоматический расчёт',result:`${fmt(level)} м`,details:`Глубина=${d} м; Pз=${z}; Pд=${p}; плотность=${rho} кг/м³`}};bind(['depth','pz','pd','density'],calc);clear.onclick=()=>{['depth','pz','pd','density'].forEach(i=>document.getElementById(i).value='');calc()};window.onbeforeunload=null}

function renderFrequency(){app.innerHTML=screen(`${topbar('Необходимая частота запуска')}<main class="content stack">${field('level','Уровень жидкости, м')}${field('head','Напор, м')}<div id="liveResult">${resultCard('Необходимая частота','','Заполните все параметры')}</div></main>`);const calc=()=>{const l=num(level.value),h=num(head.value);if(l===null||h===null||h<=0)return setResult('Необходимая частота','','Заполните все параметры');const r=50*Math.sqrt((40*9.81+l)/h);if(!Number.isFinite(r))return setResult('Необходимая частота','','Проверьте значения');setResult('Необходимая частота',`${fmt(r)} Гц`);state.last={title:'Необходимая частота запуска',method:'Автоматический расчёт',result:`${fmt(r)} Гц`,details:`Уровень=${l} м; напор=${h} м`}};bind(['level','head'],calc)}

const vkpTable={'139.7-60':0.0091,'139.7-73':0.0100,'139.7-89':0.0058,'146-60':0.0100,'146-73':0.0087,'146-89':0.0067,'168-60':0.0150,'168-73':0.0136,'168-89':0.0114,'178-60':0.0168,'178-73':0.0155,'178-89':0.0134};
const vnkt={'60':0.0020,'73':0.0030,'89':0.0045};
const casingWalls={'102':[6.5],'114':[5.2,5.7,6.4,7.4,8.6,10.2],'139.7':[6.2,7,7.7,9.2,10.5],'146':[6.5,7,7.7,8.5,9.6,10.7],'168':[7.3,8,8.9,10.6,12.1],'178':[5.9,6.9,8.1,9.2,10.4,11.5,12.7,13.7,15],'194':[7.6,8.3,9.3,10.9,12.7,16.1]};
function renderFlow(){app.innerHTML=screen(`${topbar('Определение притока')}<main class="content stack">
${selectField('flowType','Вид расчёта',['Герметичный ОК','Негерметичный ОК в период слива','Негерметичный ОК после слива'],'Герметичный ОК')}
${selectField('source','Источник Vкп',['По справочнику','По геометрии'],'По справочнику')}
<div class="card stack" id="vkpBox"></div><div class="row">${field('dh','ΔH, м')}${field('time','Время, мин')}</div><div id="hstWrap"></div><div id="liveResult">${resultCard('Приток','','Заполните параметры')}</div></main>`);function rebuildVkp(){const src=source.value;if(src==='По справочнику'){vkpBox.innerHTML=`<div class="row">${selectField('casing','ЭК',['139.7','146','168','178'],'168')}${selectField('tubing','НКТ',['60','73','89'],'73')}</div><div class="hint" id="vkpText"></div>`}else{vkpBox.innerHTML=`<div class="row">${selectField('tubing','НКТ',['60','73','89'],'73')}${selectField('casingOuter','D ЭК',Object.keys(casingWalls),'146')}</div><div id="wallHolder"></div><div class="hint" id="vkpText"></div>`;buildWall()}bind(['casing','tubing','casingOuter'],()=>{if(casingOuter)buildWall();calc()});calc()}
function buildWall(){const co=document.getElementById('casingOuter');if(!co)return;const vals=casingWalls[co.value]||[];wallHolder.innerHTML=selectField('wall','Стенка ЭК',vals,vals[0]);bind(['wall'],calc)}
function calc(){hstWrap.innerHTML=flowType.value==='Негерметичный ОК в период слива'?field('hst','Hст, м'):'';if(document.getElementById('hst'))bind(['hst'],calc);const tub=document.getElementById('tubing')?.value||'73';let vkp,detail='';if(source.value==='По справочнику'){const cas=document.getElementById('casing')?.value;vkp=vkpTable[`${cas}-${tub}`];detail=`ЭК=${cas} мм; НКТ=${tub} мм`}else{const co=num(document.getElementById('casingOuter')?.value),w=num(document.getElementById('wall')?.value),to=num(tub);if(co&&w&&to){const inner=co-2*w;if(inner>to){vkp=Math.PI/4*(inner*inner-to*to)*1e-6;detail=`НКТ=${tub} мм; D ЭК=${co} мм; стенка=${w} мм; Dвнутр=${fmt(inner)} мм`}}}const vt=document.getElementById('vkpText');if(vt)vt.textContent=vkp?`Vкп: ${vkp.toFixed(6)} м³/м`:'Не удалось определить Vкп';const D=num(dh.value),T=num(time.value);if(D===null||T===null||T<=0||!vkp)return setResult('Приток','','Заполните параметры');let r;const type=flowType.value;if(type==='Герметичный ОК')r=D*vkp*1440/T;else if(type==='Негерметичный ОК после слива')r=D*(vkp+(vnkt[tub]||0))*1440/T;else{const hs=num(document.getElementById('hst')?.value);if(hs===null)return setResult('Приток','','Введите Hст');r=((D*vkp)-(vnkt[tub]||0)*hs)*1440/T}r=Math.round(r*100)/100;setResult('Приток',`${fmt(r)} м³/сут`);state.last={title:type,method:source.value,result:`${fmt(r)} м³/сут`,details:`ΔH=${D} м; время=${T} мин; ${detail}; Vкп=${vkp.toFixed(6)} м³/м`}}
bind(['flowType'],()=>{hstWrap.innerHTML='';calc()});bind(['source'],rebuildVkp);bind(['dh','time'],calc);rebuildVkp()}

let timerInterval=null,timerStart=0,timerAccum=0;
function renderManual(){clearInterval(timerInterval);app.innerHTML=screen(`${topbar('Ручной замер дебита')}<main class="content stack">${field('liters','Набежавший объём, л')}${field('seconds','Время замера, с')}<div class="row"><button class="btn" id="timerBtn">Старт</button><button class="btn secondary" id="resetBtn">Сброс времени</button></div><div id="liveResult">${resultCard('Дебит скважины','','Введите объём и время')}</div><button class="btn secondary full" id="clear">Очистить</button></main>`);function calc(){const l=num(liters.value),s=num(seconds.value);if(!l||!s)return setResult('Дебит скважины','','Введите объём и время');const d=l*86.4/s;setResult('Дебит скважины',`${fmt(d)} м³/сут`);state.last={title:'Ручной замер дебита',method:'Турбинный объёмный расходомер',result:`${fmt(d)} м³/сут`,details:`Объём=${l} л; время=${fmt(s,1)} с`}}function updateTimer(){const ms=timerAccum+(performance.now()-timerStart);seconds.value=(ms/1000).toFixed(1);calc()}timerBtn.onclick=()=>{if(timerInterval){timerAccum+=performance.now()-timerStart;clearInterval(timerInterval);timerInterval=null;timerBtn.textContent='Продолжить';seconds.disabled=false}else{timerStart=performance.now();timerInterval=setInterval(updateTimer,100);timerBtn.textContent='Стоп';seconds.disabled=true}};resetBtn.onclick=()=>{clearInterval(timerInterval);timerInterval=null;timerAccum=0;seconds.disabled=false;seconds.value='';timerBtn.textContent='Старт';calc()};bind(['liters','seconds'],()=>{const s=num(seconds.value)||0;timerAccum=s*1000;calc()});clear.onclick=()=>{liters.value='';resetBtn.click()}}
function renderOperating(kind){const isApv=kind==='apv';app.innerHTML=screen(`${topbar(isApv?'Перевод УПР в АПВ':'Перевод ПР в УПР')}<main class="content stack"><div class="row">${field('rate','Дебит, м³/сут')}${field('potential','Потенциал, м³/сут')}</div><div class="row">${field('supply','Подача, мин')}${field('cycle','Цикл, мин',`value="${isApv?360:60}"`)}</div>${isApv?field('drain','Время слива, мин','value="60"'):''}<div id="liveResult">${resultCard('Результат','','Заполните параметры')}</div><div id="cycleAction"></div><div class="hint">${isApv?'Минимальный цикл рассчитывается независимо от выбранного: (подача + слив) / (1 − потенциал / дебит), затем округляется вверх до 60 минут. Отстой считается для выбранного цикла.':'Время работы = цикл × потенциал / дебит + время появления подачи. Остаток цикла — время остановки.'}</div></main>`);const ids=['rate','potential','supply','cycle',...(isApv?['drain']:[])];const calc=()=>{const action=document.getElementById('cycleAction');if(action)action.innerHTML='';const q=num(rate.value),p=num(potential.value),s=num(supply.value),c=num(cycle.value);if([q,p,s,c].some(v=>v===null)||q<=0||p<0||s<0||c<=0)return setResult('Результат','','Заполните параметры');const productive=c*p/q,total=productive+s,stop=c-total;if(!isApv){if(total>=c)return setResult('Результат','','Выбранный цикл слишком короткий. Увеличьте продолжительность цикла');const text=`${Math.round(total)} / ${Math.round(stop)} мин\nПолезная работа: ${Math.round(productive)} мин`;setResult('Рекомендуемый режим УПР',text);state.last={title:'Перевод ПР → УПР',method:'Автоматический расчёт',result:text,details:`Дебит=${q}; потенциал=${p}; подача=${s}; цикл=${c}`};return}const dr=num(drain.value);if(dr===null||dr<0)return setResult('Результат','','Заполните время слива');if(p>=q)return setResult('Результат','','Для режима АПВ потенциал должен быть меньше дебита УЭЦН');const req=(s+dr)/(1-p/q),minCycle=Math.ceil(req/60)*60,suitable=c>=minCycle&&stop>=dr;const text=suitable?`Работа: ${Math.round(total)} мин\nОтстой: ${Math.round(stop)} мин\nВремя слива: ${fmt(dr)} мин\nМинимальный цикл: ${minCycle} мин\nВыбранный цикл подходит`:`Минимально допустимый цикл: ${minCycle} мин`;setResult(suitable?'Рекомендуемый режим АПВ':'Выбранный цикл не подходит',text);if(!suitable&&action){action.innerHTML=`<button class="btn full" id="useMinCycle">Использовать ${minCycle} мин</button>`;document.getElementById('useMinCycle').onclick=()=>{cycle.value=String(minCycle);calc();cycle.scrollIntoView({behavior:'smooth',block:'center'})}}state.last=suitable?{title:'Перевод УПР → АПВ',method:'Автоматический расчёт',result:text,details:`Дебит=${q}; потенциал=${p}; подача=${s}; слив=${dr}; цикл=${c}`} : null};bind(ids,calc);calc()}
function renderSko(){const variants=[['direct','Прямая закачка — при снижении производительности'],['direct8','Прямая закачка — нет подачи / клин'],['reverse','Обратная закачка — УЭЦН работает'],['reverseOff','Обратная закачка — УЭЦН выключен']];app.innerHTML=screen(`${topbar('Объём СКО')}<main class="content stack"><div class="section-title">Выберите вариант обработки</div><div class="radio-list" id="variants">${variants.map((v,i)=>`<div class="radio-item pressable ${i===0?'active':''}" data-v="${v[0]}"><span>${v[1]}</span></div>`).join('')}</div>${field('skoDepth','Глубина спуска ЭЦН, м')}<div id="skoParams"></div><div id="liveResult">${resultCard('Общий объём обработки','','Введите параметры')}</div><div class="hint">Расчёт выполняется по формулам регламента. Технология, концентрация кислоты и окончательный объём определяются Планом-заказом и технологической службой.</div></main>`);let variant='direct',selectedTubing='73';function tubingSelector(){return `<div class="field"><label>НКТ</label><div class="nkt-grid" id="nktGrid">${['60','73','89'].map(t=>`<button type="button" class="nkt-option ${selectedTubing===t?'active':''}" data-t="${t}">${t} мм</button>`).join('')}</div></div>`}function bindTubing(){document.querySelectorAll('.nkt-option').forEach(el=>el.onclick=()=>{selectedTubing=el.dataset.t;document.querySelectorAll('.nkt-option').forEach(x=>x.classList.toggle('active',x===el));calc()})}function params(){if(variant==='direct'||variant==='direct8'){skoParams.innerHTML=tubingSelector()+`<div class="hint">Справочный объём: ${selectedTubing==='60'?'2':selectedTubing==='73'?'3':'4,5'} л/м</div>`;bindTubing()}else{skoParams.innerHTML=`${selectField('skoCasing','Наружный диаметр ЭК',Object.keys(casingWalls),'146')}<div id="skoWallWrap"></div>${variant==='reverse'?tubingSelector():''}`;wallBuild();if(variant==='reverse')bindTubing()}bind(['skoCasing'],()=>{wallBuild();calc()});calc()}function wallBuild(){const co=document.getElementById('skoCasing');if(!co)return;const vals=casingWalls[co.value]||[];skoWallWrap.innerHTML=selectField('skoWall','Толщина стенки ЭК',vals,vals.includes(8.5)?8.5:vals[0]);bind(['skoWall'],calc)}function calc(){const d=num(skoDepth.value);if(!d||d<=0)return setResult('Общий объём обработки','','Введите глубину спуска ЭЦН');let base,extra=0,details='';if(variant==='direct'||variant==='direct8'){const t=selectedTubing,liters=t==='60'?2:t==='73'?3:4.5;base=liters*d/1000;extra=variant==='direct8'?8:0;details=`НКТ=${t} мм`}else{const co=num(document.getElementById('skoCasing')?.value),w=num(document.getElementById('skoWall')?.value),inner=(co-2*w)/1000;if(!co||!w||inner<=0)return setResult('Общий объём обработки','','Проверьте ЭК');if(variant==='reverse'){const t=num(selectedTubing)/1000;if(!t||inner<=t)return setResult('Общий объём обработки','','Диаметр ЭК должен быть больше диаметра НКТ');base=.79*d*(inner*inner-t*t);extra=.5;details=`ЭК=${co}×${w} мм; Dнар НКТ=${selectedTubing} мм`}else{base=.79*inner*inner*d;details=`ЭК=${co}×${w} мм`}}const total=base+extra;setResult('Общий объём обработки',`${fmt(total)} м³`);state.last={title:'Объём СКО',method:variants.find(v=>v[0]===variant)[1],result:`${fmt(total)} м³`,details:`Глубина=${d} м; ${details}`}}document.querySelectorAll('.radio-item').forEach(el=>el.onclick=()=>{variant=el.dataset.v;document.querySelectorAll('.radio-item').forEach(x=>x.classList.toggle('active',x===el));params()});bind(['skoDepth'],calc);params()}
function renderTap(){app.innerHTML=screen(`${topbar('Расчёт отпайки ТМПН')}<main class="content stack"><div class="section-title">Тип станции управления</div><div class="chips"><button class="chip active" data-mode="no">Без ЧРП</button><button class="chip" data-mode="vfd">С ЧРП</button></div><div class="row">${field('trIn','Uвх ТМПН, В')}${field('supplyV','U сети, В')}</div><div class="row">${field('motorV','U ПЭД, В')}${field('motorI','I ПЭД, А')}</div><div class="row">${field('cableL','Кабель, м')}${field('cableS','Сечение, мм²')}</div>${field('temp','Температура пласта, °C')}<div class="section-title">Материал кабеля</div><div class="chips"><button class="chip active" data-mat="cu">Медь</button><button class="chip" data-mat="al">Алюминий</button></div><div class="section-title">Тип ПЭД</div><div class="chips"><button class="chip active" data-motor="async">Асинхронный</button><button class="chip" data-motor="pm">Вентильный</button></div><div id="vfdFields"></div><div id="liveResult">${resultCard('Расчётное напряжение отпайки','','Заполните параметры')}</div><div class="hint">Выберите ближайшую доступную отпайку в большую сторону.</div></main>`);let mode='no',mat='cu',motor='async',filter=false;function rebuild(){vfdFields.innerHTML=mode==='vfd'?`<div class="row">${field('vfdV','Uвых max ЧРП, В')}${field('fmax','Fmax, Гц')}</div>${field('fnom','Номинальная частота ПЭД, Гц')}<label class="switchline card"><span><b>Выходной фильтр в составе НЭО</b><br><span class="subtle">Учитывать коэффициент 1,08</span></span><input id="filter" type="checkbox"></label>`:'';if(mode==='vfd'){bind(['vfdV','fmax','fnom'],calc);filter=document.getElementById('filter').checked;document.getElementById('filter').onchange=e=>{filter=e.target.checked;calc()}}calc()}function calc(){const a=num(trIn.value),b=num(supplyV.value),u=num(motorV.value),i=num(motorI.value),l=num(cableL.value),s=num(cableS.value),t=num(temp.value);if([a,b,u,i,l,s,t].some(v=>v===null)||[a,b,u,i,l,s].some(v=>v<=0))return setResult('Расчётное напряжение отпайки','','Заполните параметры');const kt=1+.0043*(t-20),rho=mat==='cu'?.017:.026,pf=motor==='async'?.85:.95,loss=Math.sqrt(3)*i*pf*(l/s)*rho*kt;let base;if(mode==='no')base=a/b*u;else{const vm=num(document.getElementById('vfdV')?.value),fm=num(document.getElementById('fmax')?.value),fn=num(document.getElementById('fnom')?.value);if(!vm||!fm||!fn)return setResult('Расчётное напряжение отпайки','','Заполните параметры ЧРП');base=a/vm*(fm/fn)*u*(filter?1.08:1)}const req=base+loss,text=`${fmt(req,1)} В\nПотери в кабеле: ${fmt(loss,1)} В`;setResult('Расчётное напряжение отпайки',text);state.last={title:'Отпайка ТМПН',method:mode==='no'?'Без ЧРП':'С ЧРП',result:text,details:`Uвх=${a}; Uсети=${b}; UПЭД=${u}; I=${i}; кабель=${l} м; сечение=${s} мм²; T=${t}°C`}}bind(['trIn','supplyV','motorV','motorI','cableL','cableS','temp'],calc);document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{mode=x.dataset.mode;document.querySelectorAll('[data-mode]').forEach(y=>y.classList.toggle('active',y===x));rebuild()});document.querySelectorAll('[data-mat]').forEach(x=>x.onclick=()=>{mat=x.dataset.mat;document.querySelectorAll('[data-mat]').forEach(y=>y.classList.toggle('active',y===x));calc()});document.querySelectorAll('[data-motor]').forEach(x=>x.onclick=()=>{motor=x.dataset.motor;document.querySelectorAll('[data-motor]').forEach(y=>y.classList.toggle('active',y===x));calc()});rebuild()}

function renderHistory(){const list=history();app.innerHTML=screen(`${topbar('История расчётов')}<main class="content stack">${list.length?`<button class="btn danger full" id="clearHistory">Очистить историю</button>${list.map(x=>`<div class="card history-item"><div class="title">${esc(x.title)}</div><div class="date">${new Date(x.ts).toLocaleString('ru-RU')}</div><div class="history-result">${esc(x.result)}</div><div class="subtle">${esc(x.method||'')}</div><div class="hint">${esc(x.details||'')}</div></div>`).join('')}`:'<div class="empty">История пока пустая.<br>Выполненные расчёты будут сохраняться на этом устройстве.</div>'}</main>`,'history');document.getElementById('clearHistory')?.addEventListener('click',()=>{if(confirm('Очистить всю историю?')){clearHistory();renderHistory()}})}


