const assistantTopics=[{"title":"Отключение по перегрузке","steps":["Зафиксировать время и рабочую частоту, при которой произошла остановка.","Дождаться окончания слива столба жидкости из НКТ и прекращения турбинного вращения.","Проверить возможные причины: сопротивление вращению насоса, напряжение ТМПН, мощность ПЭД, изоляцию.","Повторные пуски и режимы расклинки выполнять только в установленном порядке; между попытками обеспечить охлаждение ПЭД."],"preserve":false},{"title":"Срыв подачи","steps":["Проверь скважину на герметичность ОК.","Проверь, есть ли точно проход по манифольдной линии и коллектору.","Убедись, что на скважине нет гидратопарафиновой пробки.","Возможно, скважина «укачалась»: уровень жидкости слишком упал. Посмотри по архиву давление приёма — оно могло плавно уменьшаться, и при данной частоте скважине не хватает напора.","Мазут в затрубе является следствием либо негерметичности ОК, либо гидратопарафиновой пробки.","Если скважина не «укачана» и при этом не грузится, возможно появление газовой пробки в НКТ или рабочих органах УЭЦН. Хороший вариант — полностью стравить НКТ и затрубное пространство на ДЕ.","Если это не помогло, технолог отправляет звено промывки.","После стравливания можно поднять частоту, чтобы газ в рабочих органах УЭЦН быстрее заместился флюидом и появилась подача. После восстановления устойчивой подачи вернуть рабочий режим."],"preserve":false},{"title":"Промывка","steps":["Перед началом мероприятия желательно стравить газ из затрубного пространства.","Обратная промывка осуществляется при работающем насосе.","Скважина должна находиться на замере для контроля подачи.","Частоту необходимо понизить и подобрать «золотую середину»: не допустить исчезновения подачи и перегрева установки, но и не оставлять слишком высокую частоту.","Обязательно выполнить циклическую распрессовку насосом через манифольдную задвижку. Поднимая и снижая давление, создают толчки и перемешивание жидкости в насосе и НКТ, что повышает эффективность промывки."],"preserve":false},{"title":"Скважина не выходит на режим","steps":["Сравнить фактический дебит, динамический уровень или давление на приёме с расчётными параметрами.","Проверить направление вращения, герметичность лифта НКТ и обратного клапана.","Проверить АГЗУ, проход до АГЗУ, рабочую частоту и напряжение ПЭД.","Продолжать контроль притока после каждого замера до достижения безопасного притока для охлаждения ПЭД."],"preserve":false},{"title":"Нет подачи после запуска","steps":["Сверить фактическое время с расчётным временем появления подачи.","Проверить открытие арматуры и свободный проход до АГЗУ.","Оценить уровень в НКТ, напор и правильность направления вращения.","При отсутствии подачи не оставлять УЭЦН длительно работающей без подтверждённого притока."],"preserve":false},{"title":"Высокая температура ПЭД","steps":["Проверить наличие срыва подачи и достаточность притока для охлаждения.","Сопоставить температуру ПЭД с рабочим током, загрузкой и давлением на приёме.","Проверить достоверность ТМС и отсутствие ухудшения охлаждения из-за газа или низкого уровня.","При достижении предельной температуры действовать по уставкам защит и требованиям технологической службы."],"preserve":false},{"title":"Частые АПВ","steps":["Проверить, успевает ли завершиться слив до следующего запуска.","Сопоставить цикл с временем работы, появления подачи и обязательным временем слива.","Проверить причины отключений: ЗСП, перегрузка, питание, уровень и газ.","При выносе абразивных частиц избегать режима АПВ без согласованного технического решения."],"preserve":false},{"title":"Отогрев вентиля зимой","steps":["если нужно замерить давление зимой или отобрать пробу, ни в коем случае нельзя пользоваться открытым огнем и заостренными приспособлениями. Огонь, и так понятно, что не дружит с взрывоопасными газами и веществами, а вот заточка может вылете вместе с содержимыми осколками гидрата и льда. Скорость вылета не маленькая, получиться картечь.","Как действовать?","Напротив вентиля не стой. Открой закрой его пару раз, возможно, это поможет. Ежели там сильная пробка замерзшая, то нужно отогреть теплой водой или паром. вызывать ППУ из-за вентиля сомнительная затея. Если рядом есть бригада КРС, ГРП,ЗБС и других подрядчиков попроси у них теплой воды с чайника. Закрытый вентиль облей теплой водой. быстро не лей, по тихоньку. через минуту- две открой вентиль.","Для профилактики зимой не закрывай тихо вентиль. Нужно перед окончанием манипуляций стравить остатки с застойной зоны. Например, отбирал пробу, пока бирки ставил скважина встала как раз по программе, открыл вентиль посильнее продул этот участок. Это не гарантии от заморозки вентиля, но в большинстве случаев это может спасти от лишних проблем."],"preserve":true},{"title":"Остановка водовода зимой","steps":["Иногда зимой могут попросить закрыть скважину ППД на избыток. Просто закрыть скважину и уйти - ошибка, которая может стоить ремонтом выкидной линии. При закрытии вода останется и замерзнет. Вода при замерзании расширяется и может силой природы разорвать металл и вызвать отказ трубопровода.","Как же быть?","Нужно определиться с задвижками. Закрой манифольдную задвижку и секущую на водоводе и страви давление в манифольдной линии через вентиль. Понаблюдай не набирает ли давление. Если все отлично, ничего не шумит по задвижкам и нет наполнения водой участка трубопровода, то делай видимый разрыв в самой максимально нижней точке по фланцам. Расслабляй фланцевую пару на участке стравленного давления, обязательно повесь предупреждающий плакат, что данный водовод отсечен от линии и вставь ярко видимую палку идентификатор в разрез между фланцами, чтоб люди издалека видели негерметичность трубопровода. Обязательно убедись в отсутствии течи по фланцевой паре."],"preserve":true},{"title":"ППД замер давления","steps":["Замерить давление ППД иногда физически возможно без использования ППУ. Такое реализовать возможно, когда ,например, в уровень жидкости в затрубе неполный ( т.е. уровень где то внизу) и при этом не стравливали с затруба жидкость ( не выбрасывали мазут с водой с затруба). То есть, участок до вентиля на затрубной линии \"сухой\", вентиль не заморожен. Такое же может произойти с замером давления на буфере.","Ежели при открытии вентиля ничего не происходит, где бы это не было, и при этом задвижки непонятно в каком состоянии закрытом или открытом, то не стоит гадать- смело вызывай ППУ. Бери хороший большой мешок и парь скважину. Когда парить будешь смотри , чтоб вентили были закрыты, в том числе и замороженные."],"preserve":true},{"title":"Запуск скважины ВНР","steps":["1) Перед запуском, подойди к электромонтерам, узнай у них показания ТМС, по ним рассчитай статический уровень в затрубном пространстве. По этому уровню уже рассчитаешь частоту, на которой скважина в теории должна свое выдавать.","2) После этого проверь проход в АГЗУ. Задвижка на группу открыта точно?","3) КРС должен опрессовать лифт НКТ и ФА. Проследи, что подрядчики прессуют именно лифт, а не участок до буферной задвижки — проверь, что буферная и центральная задвижка открыты. Опрессовка обычно занимает по времени минут 15–20. Как давление поднимут 60 атмосфер, то на агрегате проверь его. Жди 10 минут. Если держит, то давай команду убирать агрегат.","4) КРС убрал агрегат и бочку. Закрываешь уравнительную. Ставишь манометр в манифольдную линию. Открываешь манифольд. (Запускаешь оставшееся давление с трубок в линию.) В линии будет какое-то давление. В затрубе обычно ноль или незначительное давление. Открываешь уравнительную задвижку и смотришь, падение давления есть или нет. Оно может чутка упасть на 1–3 атмосферы и потом закроется клапан обратный — это нормально. Главное, что клапан КРС правильно установил и он герметичен. Если клапан пропускает, не стесняйся, иди к старшему бурильщику или мастеру КРС и пусть открывают, смотрят. Если допустишь негерметичность клапана сегодня, то завтра будешь менять его сам.","!ВНИМАНИЕ! Зимой обязательно не отпускай КРС сразу. Накачай в линию пару кубов! Вдруг там непроход, вдруг не стравили линию перед заездом КРС и там всё заморожено, или просто прихватило. Если обнаружишь, что там непроход и давление держит, то ищем, где непроход и парим.","Обычно при нижней обвязке скважины он находится где вниз уходит труба выкидная от скважины. Но если ты покачал агрегатом пару десятков секунд и потом только обнаружился непроход, то он дальше по трубе. Где труба выходит из земли напротив своего отвода. Кстати, возможен непроход и на обратном клапане перед АГЗУ.","Когда паришь скважину, переводи её на дренажную ёмкость и не в открытом положении. То есть попарил полчасика, потом пошёл открыл задвижку на ДЕ. Пошло, пошуршало — значит всё ок, устранили непроход.","Почему на ДЕ? Потому что то, что забило трубу, может улететь в сепарационную ёмкость и забить приборы. Потом не забудь при запуске обратно перевести в линию скважину.","5) Итак, клапан прессанули, проход в линии есть. Электромонтёры сделали свои дела: подключили СУ и ШПВ. Обмениваешься контактами с электромонтёрами, они запускают скважину на 35 герцах на обратном вращении. Записывают показания токов, потом на прямом. Если на прямом значительно параметры лучше, то давай им команду разгонять скважину до твоих герц расчётных, которые ты уже рассчитал.","В этот момент ты стоишь на скважине, манометр на манифольдной линии, ждёшь подачи. Ждать подачи с закрытой задвижкой опасно, пусть она будет открыта. Время от времени слушай трубу, она «зашелестит». Пробуй аккуратно закрывать секущую задвижку. Зафиксируй время опрессовки за 35–40 атмосфер.","Сразу бежать прессовать не надо. Первое время запуска параметры работы скважины могут плавать. Подожди минут 5. Дай команду на разворот вращения электромонтёрам. Они остановят её и развернут вращение. Запуск — и также жди подачи и пробуй прессовать минут через 5.","Обычно на обратном вращении подачи не бывает. Исключения, конечно, бывают, где огромный потенциал — ВНС, где на приёме по 200–400 атмосфер. Если на обратном вращении подачи нет и опрессовки соответственно тоже, то делай заключение о прямом вращении вала как прямое — верное. Обратно меняй вращение на прямое фактически верное.","6) Ставь скважину на замер. И жди замер хотя бы получасовой. Паспорт скважины не забудь забрать у электромонтёра. С замером и параметрами работы скважины передавай информацию технологу.","7) И да, нужно передать запуск на пульт управления в цеху."],"preserve":true}];

function refCard(icon,title,subtitle,action){return `<div class="card menu-card pressable" onclick="${action}"><div class="emoji">${iconSvg(icon)}</div><div class="grow"><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></div><div class="chev">›</div></div>`}
function openRefInfo(title,text){state.refInfo={title,text};go('refinfo')}
function renderRefInfo(){const x=state.refInfo||{title:'Справочник',text:''};app.innerHTML=screen(`${topbarTo(x.title)}<main class="content"><div class="card ref-text">${esc(x.text).replace(/\n/g,'<br>')}</div></main>`,'reference')}


const referenceInfo = {
  pedLowFlow: {
    title: 'Работа ПЭД при недостаточном притоке',
    text: 'До 32 кВт включительно:\nне более 2 часов работы + 1,5 часа охлаждения.\n\nБолее 32 до 45 кВт включительно:\nне более 1 часа работы + 1,5 часа охлаждения.\n\nСвыше 45 кВт:\nне более 30 минут работы + 1,5 часа охлаждения.'
  },
  pedTemp: {
    title: 'Температурные группы ПЭД',
    text: 'Первая группа — до 120 °C.\n\nВторая группа — до 150 °C.\n\nТретья группа — до 170 °C.'
  },
  zsp: {
    title: 'Уставки ЗСП',
    text: 'Загрузка ПЭД 70% и более — 85–88%.\n\nЗагрузка ПЭД от 50 до 70% — 90–92%.\n\nЗагрузка ПЭД менее 50% — 92–95%.'
  },
  vnr: {
    title: 'Данные при передаче запуска ВНР',
    get text(){ return vnrText; }
  }
};
function openRefKey(key){const x=referenceInfo[key];if(!x)return;state.refInfo={title:x.title,text:x.text};go('refinfo')}

function renderReference(){app.innerHTML=screen(`${topbar('Справочник')}<main class="content stack">
${refCard('⚙','Необходимый приток для охлаждения ПЭД','Расчёт притока при номинальной и фактической загрузке',"go('ped')")}
${refCard('⏱','Работа ПЭД при недостаточном притоке','Допустимое время работы и охлаждения',"openRefKey('pedLowFlow')")}
${refCard('🌡','Температурные группы ПЭД','Допустимая температура пластовой жидкости',"openRefKey('pedTemp')")}
${refCard('zsp','Уставки защиты от срыва подачи','Рекомендуемые значения ЗСП по загрузке ПЭД',"openRefKey('zsp')")}
${refCard('⚠','Аварийные остановки и нештатные режимы','Алгоритмы действий по производственным ситуациям',"go('assistant')")}
${refCard('ℹ','Данные при передаче запуска ВНР','Справочная информация для передачи запуска на пульт',"openRefKey('vnr')")}
${refCard('pipeLarge','Обсадные трубы — ГОСТ 632-80','Диаметры ЭК, толщины стенок и внутренние диаметры',"state.pipeType='casing';go('pipes')")}
${refCard('pipeSmall','НКТ — ГОСТ 633-80','НКТ 60, 73, 89 мм: стенки и внутренние диаметры',"state.pipeType='tubing';go('pipes')")}
${refCard('sko','Соляно-кислотная обработка УЭЦН','Формулы, объёмы, ограничения и критерии СКО',"go('skoref')")}
${refCard('ⓘ','О приложении','Версия, сведения и политика конфиденциальности',"go('about')")}
<div class="install-note"><b>Установка на iPhone:</b> Safari → «Поделиться» → «На экран Домой». После первой полной загрузки приложение работает офлайн.</div>
</main>`,'reference')}

function renderPipes(){const tubing=state.pipeType==='tubing';const data=tubing?tubingGost633:casingGost632Full;const title=tubing?'НКТ':'Обсадные трубы';const standard=tubing?'ГОСТ 633-80 — трубы насосно-компрессорные и муфты к ним. Для НКТ 60, 73 и 89 мм показаны наружный диаметр, толщины стенок и внутренний диаметр.':'ГОСТ 632-80 — трубы обсадные и муфты к ним. В справочнике приведены используемые в приложении ЭК 114–194 мм; 219 мм не включена.';app.innerHTML=screen(`${topbarTo(title)}<main class="content stack"><div class="card"><b>${standard}</b></div>${Object.entries(data).map(([nom,p])=>`<div class="card pipe-card"><h3>${nom} мм</h3>${p.walls.map(w=>`<div class="pipe-row"><span>Стенка ${fmt(w,1)} мм</span><b>Dвн ${fmt(p.outside-2*w,1)} мм</b></div>`).join('')}</div>`).join('')}</main>`,'reference')}

let pedDb=null;
async function loadPedDb(){if(pedDb)return pedDb;const r=await fetch('./assets/PedCoolingDatabase.json');if(!r.ok)throw new Error('Не удалось загрузить справочник ПЭД');pedDb=await r.json();return pedDb}
function uniqueSorted(a,numeric=true){return [...new Set(a)].sort((x,y)=>numeric?x-y:String(x).localeCompare(String(y),'ru'))}
async function renderPed(){
  app.innerHTML=screen(`${topbarTo('Охлаждение ПЭД')}<main class="content stack"><div class="card"><b>Необходимый приток для охлаждения ПЭД</b><div class="hint">Поля специально оставлены пустыми. Выберите параметры своего ПЭД — приложение не подставляет примерные значения автоматически.</div></div><div id="pedBody" class="stack"><div class="card">Загрузка справочника…</div></div></main>`,'reference');
  try{const db=await loadPedDb();state.pedSel={};renderPedBody(db)}catch(e){document.getElementById('pedBody').innerHTML=`<div class="card error">${esc(e.message)}</div>`}
}
function pedSelectHtml(id,label,values,val=''){
  const opts=[`<option value="">— Выберите —</option>`,...values.map(o=>`<option value="${esc(o)}" ${String(o)===String(val)?'selected':''}>${esc(o)}</option>`)].join('');
  return `<div class="field"><label>${esc(label)}</label><select id="${id}">${opts}</select></div>`
}
function renderPedBody(db){
  const s=state.pedSel||{};
  const dias=uniqueSorted(db.map(x=>x.diameter));
  let html=pedSelectHtml('pedDia','Диаметр ПЭД, мм',dias,s.diameter||'');
  if(!s.diameter){html+=`<div class="card hint">Начните с выбора диаметра ПЭД.</div>`;document.getElementById('pedBody').innerHTML=html;bindPedSelects(db);return}
  const dia=Number(s.diameter);
  const pows=uniqueSorted(db.filter(x=>x.diameter===dia).map(x=>x.power));
  html+=pedSelectHtml('pedPower','Мощность, кВт',pows,s.power||'');
  if(!s.power){html+=`<div class="card hint">Теперь выберите мощность ПЭД.</div>`;document.getElementById('pedBody').innerHTML=html;bindPedSelects(db);return}
  const power=Number(s.power);
  const cas=uniqueSorted(db.filter(x=>x.diameter===dia&&x.power===power).map(x=>x.casing));
  html+=pedSelectHtml('pedCasing','Обсадная колонна, мм',cas,s.casing||'');
  if(!s.casing){html+=`<div class="card hint">Выберите диаметр обсадной колонны.</div>`;document.getElementById('pedBody').innerHTML=html;bindPedSelects(db);return}
  const casing=Number(s.casing);
  const walls=uniqueSorted(db.filter(x=>x.diameter===dia&&x.power===power&&x.casing===casing).map(x=>x.wall));
  html+=pedSelectHtml('pedWall','Толщина стенки, мм',walls,s.wall||'');
  if(!s.wall){html+=`<div class="card hint">Выберите толщину стенки обсадной колонны.</div>`;document.getElementById('pedBody').innerHTML=html;bindPedSelects(db);return}
  const wall=Number(s.wall);
  const results=db.filter(x=>x.diameter===dia&&x.power===power&&x.casing===casing&&Math.abs(x.wall-wall)<1e-9);
  html+=`<div class="section-title">Найдено ПЭД: ${results.length}</div><div class="stack">${results.map((p,i)=>`<div class="card ped-result" data-ped="${i}"><b>${esc(p.name)}</b><div class="hint">${esc(p.manufacturer)}</div><div class="ped-flow">Номинальный приток: <b>${fmt(p.flow)} м³/сут</b></div></div>`).join('')||'<div class="card">Подходящие ПЭД не найдены</div>'}</div><div id="pedDetails"></div>`;
  document.getElementById('pedBody').innerHTML=html;
  bindPedSelects(db);
  document.querySelectorAll('[data-ped]').forEach(el=>el.onclick=()=>renderPedDetails(results[Number(el.dataset.ped)]));
}
function bindPedSelects(db){
  const map={pedDia:'diameter',pedPower:'power',pedCasing:'casing',pedWall:'wall'};
  Object.keys(map).forEach(id=>{const el=document.getElementById(id);if(!el)return;el.onchange=e=>{
    const key=map[id];const value=e.target.value;state.pedSel[key]=value?Number(value):'';
    if(id==='pedDia'){state.pedSel.power='';state.pedSel.casing='';state.pedSel.wall=''}
    if(id==='pedPower'){state.pedSel.casing='';state.pedSel.wall=''}
    if(id==='pedCasing'){state.pedSel.wall=''}
    renderPedBody(db)
  }})
}
function renderPedDetails(p){
  const d=document.getElementById('pedDetails');if(!d)return;
  d.innerHTML=`<div class="card stack"><h3 style="margin:0">${esc(p.name)}</h3><div class="row"><div><span class="subtle">Производитель</span><br><b>${esc(p.manufacturer)}</b></div><div><span class="subtle">Номинальный приток</span><br><b>${fmt(p.flow)} м³/сут</b></div></div><div class="row">${field('pedWork','Рабочий ток, А')}${field('pedNom','Номинальный ток, А')}</div><div id="pedCalc" class="result card"><h4>Необходимый приток</h4><div class="error">Введите рабочий и номинальный ток</div></div></div>`;
  const calc=()=>{const w=num(document.getElementById('pedWork').value),n=num(document.getElementById('pedNom').value);const box=document.getElementById('pedCalc');if(w===null||n===null||w<0||n<=0){box.innerHTML='<h4>Необходимый приток</h4><div class="error">Введите рабочий и номинальный ток</div>';return}const flow=p.flow*(w/n)*(w/n);box.innerHTML=`<h4>Необходимый приток при фактической загрузке ПЭД</h4><div class="value">${fmt(flow)} м³/сут</div>`};
  bind(['pedWork','pedNom'],calc)
}

function renderAssistant(){const selected=state.assistantIndex;if(selected===undefined||selected===null){app.innerHTML=screen(`${topbarTo('Помощник оператора')}<main class="content stack"><div class="section-title">Выберите ситуацию</div>${assistantTopics.map((t,i)=>`<div class="card assistant-topic" onclick="state.assistantIndex=${i};renderAssistant()"><b>${esc(t.title)}</b><span>›</span></div>`).join('')}</main>`,'reference');return}const t=assistantTopics[selected];app.innerHTML=screen(`${topbarTo(t.title,'assistant')}<main class="content"><div class="card warning-card ref-text">${t.steps.map((step,i)=>`<p>${esc(t.preserve?step:`${i+1}. ${step}`)}</p>`).join('')}</div></main>`,'reference');document.querySelector('.back').onclick=()=>{state.assistantIndex=null;renderAssistant()}}

function renderSkoReference(){const cards=[
['Кислотная композиция','• Через НКТ — 1,5 м³ кислотной композиции.\n• Через затрубное пространство — 3 м³.\n• Применяются растворы 5%, 10% и 12%.\n• Для профилактики — 5%.\n• До 12% при расклинивании — только по решению ОРМФ.\n• Продавка — водным раствором ПАВ 0,1–1,0%.'],
['Справочные объёмы НКТ','НКТ 60 — 2 л/м\nНКТ 73 — 3 л/м\nНКТ 89 — 4,5 л/м'],
['Варианты расчёта','1. Прямая, работающий УЭЦН:\nVобр = Vнкт × Lэцн / 1000\n\n2. Прямая, нет подачи / клин:\nVобр = Vнкт × Lэцн / 1000 + 8 м³\n\n3. Обратная, работающий УЭЦН:\nVобр = 0,79 × Lэцн × (Dс² − Dнкт²) + 0,5\n\n4. Обратная, насос выключен:\nVобр = 0,79 × Dс² × Lэцн\n\nДля вариантов 3 и 4 диаметры используются в метрах.'],
['Ограничения по времени','• Профилактическая промывка: кислота в зоне насоса — не более 20 минут.\n• Расклинивание без циркуляции — не более 60 минут.\n• При обратной обработке учитывается скорость оседания раствора 100–150 м/ч.'],
['Ограничения по проведению','• Не более 3 СКО за скользящий месяц.\n• Не более 5 СКО за одну эксплуатацию ЭПО.\n• Повторная обработка — после оценки причины и эффективности предыдущих работ.'],
['Критерии применения','• Снижение или отсутствие подачи.\n• Снижение подачи более чем на 5–20% от установившегося режима.\n• Остановка по причине «КЛИН».\n• Нет эффекта после промывки технологической жидкостью.\n• Подтверждённые солеотложения.\n• Частые остановки по ЗП при исправном наземном оборудовании.'],
['Когда СКО исключается','• Нет подачи и отсутствует циркуляция при промывке.\n• Высокий динамический уровень.\n• Высокое давление или противодавление закачки.\n• Повторная обработка неэффективна при аномально низком пластовом давлении.']
];app.innerHTML=screen(`${topbarTo('Соляно-кислотная обработка УЭЦН')}<main class="content stack">${cards.map(([t,x])=>`<div class="card ref-text"><h3>${esc(t)}</h3>${esc(x).replace(/\n/g,'<br>')}</div>`).join('')}<div class="card warning-card"><b>Технология, концентрация кислоты, объём обработки и необходимость отключения УЭЦН определяются технологической службой и указываются в Плане-заказе.</b></div></main>`,'reference')}

function renderAbout(){app.innerHTML=screen(`${topbar('О приложении')}<main class="content stack" style="text-align:center"><img src="assets/logo.png" style="width:min(56vw,240px);margin:0 auto;display:block" alt="Оператор ДНГ"><h2 style="margin-bottom:0">Инженерные расчёты</h2><div class="hint">Расчёты выполняются локально на устройстве.</div><div>Версия ${APP_VERSION}</div><button class="btn full" onclick="go('privacy')">Политика конфиденциальности</button></main>`,'reference')}
function renderPrivacy(){app.innerHTML=screen(`${topbar('Политика конфиденциальности')}<main class="content policy"><p><b>Приложение «Оператор ДНГ»</b> предназначено для выполнения инженерных расчётов и работает локально на устройстве пользователя.</p><h2>1. Сбор персональных данных</h2><p>Приложение не требует регистрации и не запрашивает имя, номер телефона, адрес электронной почты, паспортные или иные персональные данные.</p><h2>2. Вводимые данные</h2><p>Параметры, которые пользователь вводит для расчётов, используются только для выполнения вычислений. История расчётов, если пользователь её использует, хранится локально на устройстве.</p><h2>3. Передача третьим лицам</h2><p>Приложение не передаёт пользовательские данные третьим лицам, рекламным сетям или разработчику.</p><h2>4. Реклама и аналитика</h2><p>Приложение не содержит рекламных систем и сторонней аналитики.</p><h2>5. Доступ к функциям устройства</h2><p>Приложение не требует доступа к контактам, сообщениям, фотографиям, микрофону, камере или геолокации для выполнения основных расчётов.</p><h2>6. Офлайн-работа</h2><p>После первой загрузки файлы приложения могут сохраняться браузером для работы без интернета. Локальные данные можно удалить средствами браузера или удалением веб-приложения.</p><h2>7. Изменения политики</h2><p>Политика может обновляться при изменении функциональности приложения.</p></main>`,'reference')}

function openHomeFromStart(){state.route='home';state.navStack=[];render();scrollTo(0,0)}
function renderNotice(){app.innerHTML=`<div class="notice"><div class="panel card"><img src="assets/logo.png" style="width:130px;display:block;margin:0 auto 14px"><h1>Конфиденциальность</h1><p>Приложение работает локально и не передаёт введённые данные разработчику или третьим лицам.</p><p>Перед использованием вы можете ознакомиться с Политикой конфиденциальности.</p><div class="actions"><button class="btn secondary full" id="policyFirst">Открыть политику</button><button class="btn full" id="continueFirst">Продолжить</button></div></div></div>`;policyFirst.onclick=()=>{state.route='privacy';state.navStack=[];render();scrollTo(0,0)};continueFirst.onclick=()=>{localStorage.setItem('privacy_seen','1');openHomeFromStart()}}
function renderSplash(){state.route='splash';app.innerHTML=`<div class="splash"><div class="center"><img src="assets/logo.png" alt="Оператор ДНГ"><div class="tag">Инженерные расчёты</div></div><div class="meta">Автор<strong>Муса Якупов</strong>Версия ${APP_VERSION}</div></div>`;setTimeout(()=>{if(localStorage.getItem('privacy_seen'))openHomeFromStart();else renderNotice()},1200)}

function saveLastIfNeeded(){state._last=null}
window.go=function(route){if(route===state.route)return;if(state.route)state.navStack.push(state.route);resetHistoryDraft();state.route=route;render();scrollTo(0,0)};window.goBack=goBack
function render(){clearInterval(timerInterval);timerInterval=null;switch(state.route){case'home':return renderHome();case'level':return renderLevel();case'frequency':return renderFrequency();case'flow':return renderFlow();case'manual':return renderManual();case'upr':return renderOperating('upr');case'apv':return renderOperating('apv');case'sko':return renderSko();case'tap':return renderTap();case'history':return renderHistory();case'reference':return renderReference();case'refinfo':return renderRefInfo();case'ped':return renderPed();case'assistant':return renderAssistant();case'pipes':return renderPipes();case'skoref':return renderSkoReference();case'about':return renderAbout();case'privacy':return renderPrivacy();default:return renderHome()}}


function setupPressFeedback(){
  const selector='.btn,.menu-card,.nav-btn,.back,.radio-item,.chip,.assistant-topic,.ped-result,.nkt-option';
  document.addEventListener('pointerdown',e=>{
    const el=e.target.closest?.(selector);if(!el)return;
    el.classList.add('pressed');
    if(navigator.vibrate){try{navigator.vibrate(10)}catch{}}
  },{passive:true});
  const clear=e=>{const el=e.target.closest?.(selector);if(el)el.classList.remove('pressed')};
  document.addEventListener('pointerup',clear,{passive:true});
  document.addEventListener('pointercancel',clear,{passive:true});
  document.addEventListener('pointerleave',clear,{passive:true});
}
setupPressFeedback();

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}
